    "translatableHash": "sha256:49eac1b6718a39b19a4b75a5d7ef3ec65172241bf9c012b5a554fcb774a7f739",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Repeater Crossbow Trap",
      "level": 5,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "mechanical",
        "trap"
      ],
      "description": "A pressure plate in the hallway floor releases a latch, causing a ceiling panel to drop down. A +1 striking heavy crossbow contained in a steel box sprays bolts at any creatures in the hallway.",
      "armorClass": 22,
      "hitPoints": 50,
      "hardness": 12,
      "stealth": {
        "modifier": 13,
        "details": "(trained)"
      },
      "disable": "check (thievery, dc:20, name:Disengage the reloading mechanism, traits:hazard,complex,mechanical,trap) (Expert) or check (crafting, dc:20, name:Disengage the reloading mechanism, traits:hazard,complex,mechanical,trap) (Trained) to disengage the reloading mechanism; the trap can also be disabled by the switch in area F2",
      "isComplex": true,
      "routine": "(3 actions) The repeater crossbow trap reloads (2 actions) then Strikes a random creature in the hallway.",
      "reset": "The trap runs out of ammo after it fires 5 bolts; it must be manually reloaded.",
      "saves": {
        "fortitude": 15,
        "reflex": 9,
        "will": 0
      },
      "defenses": {
        "immunities": [
          "critical-hits",
          "precision"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "BhwFjVsraJcLLbrF",
          "name": "Auto-Bolter",
          "kind": "reaction",
          "description": "Trigger An object or creature weighing at least 25 pounds steps on the pressure plate at the south end of the hallway\nEffect A +1 striking heavy crossbow encased in a steel box drops from the ceiling and fires. The repeater crossbow trap Strikes a random creature in the hallway. The trap then rolls initiative.",
          "traits": []
        }
      ]
    }
