    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Avian Rage",
      "level": 18,
      "rarity": "rare",
      "size": "medium",
      "traits": [
        "environmental"
      ],
      "description": "Hundreds of panicked whippoorwills swarm through the area.",
      "armorClass": 0,
      "hitPoints": 0,
      "hardness": 0,
      "stealth": {
        "modifier": 45,
        "details": "(master)"
      },
      "disable": "check (nature, dc:43) (master) to calm the birds, check (occultism, dc:45) (master) to alter your aura, or check (performance, dc:45) (master) to imitate the living",
      "isComplex": true,
      "routine": "(1 action) The birds swarm wildly through the garden, pecking and slashing at all undead creatures and creatures with void healing in the garden, dealing 3d10+20 slashing damage and 1d10 persistent bleed damage (check (reflex, dc:44, basic)).",
      "reset": "The trap deactivates and resets if 1 minute passes without any undead or creatures with void healing in the garden.",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "bY2346FMb02WfLK5",
          "name": "Panic!",
          "kind": "reaction",
          "description": "Trigger An undead or a creature with void healing enters the garden\nEffect The birds screech in panic, dealing 3d12+20 sonic damage to all creatures in the garden (check (fortitude, dc:44, basic)). On a failure, the creature becomes Stunned 1 (Stunned 3 on a critical failure). The trap then rolls initiative.",
          "traits": [
            "sonic"
          ]
        }
      ]
    }
